            r = os.path.normpath(os.path.join(rel, dn))
            if os.path.islink(p):
                out[r] = {"t": "l", "to": os.readlink(p)}
                dirnames.remove(dn)
            elif dirs == "all" or (dirs == "empty" and not os.listdir(p)):
                out[r] = {"t": "d"}
        for fn in files:
            p = os.path.join(d, fn)
            r = os.path.normpath(os.path.join(rel, fn))
