#!/bin/bash
# backup.sh SRC DEST : write DEST/backup.tar holding everything in SRC
[ $# -eq 2 ] && [ -d "$1" ] || { echo "usage: backup.sh SRC DEST" >&2; exit 2; }
mkdir -p -- "$2" || exit 1
tar -cf "$2/backup.tar" -C "$1" . || exit 1
echo "backup done"

